def signed_log(x):return np.sign(x)*np.log1p(np.abs(x))

def switches(mask):
    if not isinstance(mask,str) or len(mask)!=6 or set(mask)-{'0','1'}:
        raise ValueError('Expected six-bit configuration')
    return tuple(v=='1' for v in mask)

def cluster(x,n_clusters,mask):
    a,b,c,d,e,f=switches(mask); steps=[]
    if a:steps.append(('signed_log',FunctionTransformer(signed_log)))
    if b:steps.append(('scale',StandardScaler()))
    if c:steps.append(('pca',PCA(n_components=.95,svd_solver='full',whiten=e)))
    steps.append(('model',KMeans(n_clusters=n_clusters,n_init=10 if d else 1,random_state=17,
                                     max_iter=300,algorithm='lloyd',init='random' if f else 'k-means++')))
    return Pipeline(steps).fit_predict(x)
